\label{thm:catoni-maurer}
Let Assumption~\ref{ass:bounded-loss} hold. Let $\pi_0$ be any prior distribution on $(\Theta, \mathcal{B}_\Theta)$ chosen independently of the training sample $S$. Then for any $\delta \in (0, 1)$, with probability at least $1 - \delta$ over the random draw of $S \sim \mathcal{D}^n$, the following inequality holds simultaneously for all posterior distributions $\pi_n$ on $\Theta$:
\begin{equation}
\label{eq:catoni-bound}
\mathrm{kl}\big(\hat{R}_S(\pi_n) \,\|\, R(\pi_n)\big) \le \frac{\mathrm{KL}(\pi_n \,\|\, \pi_0) + \ln \frac{2\sqrt{n}}{\delta}}{n},
\end{equation}
where $\mathrm{kl}(q \,\|\, p) = q \ln \frac{q}{p} + (1 - q) \ln \frac{1 - q}{1 - p}$ is the binary relative entropy. Applying Pinsker's inequality $\mathrm{kl}(q \,\|\, p) \ge 2(p - q)^2$ yields McAllester's form:
\begin{equation}
\label{eq:mcallester-form}
R(\pi_n) \le \hat{R}_S(\pi_n) + \sqrt{\frac{\mathrm{KL}(\pi_n \,\|\, \pi_0) + \ln \frac{2\sqrt{n}}{\delta}}{2n}}.
\end{equation}

\label{prop:weight-divergence}
Let $f_\theta: \mathcal{X} \to \mathcal{Y}$ be an $L$-layer neural network parameterized by $\theta = (W_1, \dots, W_L) \in \mathbb{R}^D$ with 1-Lipschitz activations $\sigma$ and layer width $W$. Let $\hat{\theta}$ be an empirical risk minimizer, and let $\pi_n = \mathcal{N}(\hat{\theta}, \sigma_{\mathrm{post}}^2 I_D)$ be a perturbed posterior. 

If the posterior preserves the empirical risk within margin $\epsilon_0 > 0$, i.e., $\mathbb{E}_{\theta \sim \pi_n}[|f_\theta(x) - f_{\hat{\theta}}(x)|] \le \epsilon_0$, then the tolerable posterior perturbation variance must collapse as $\sigma_{\mathrm{post}} \le \mathcal{O}(W^{-(L-1)})$. Consequently, for an isotropic Gaussian prior $\pi_0 = \mathcal{N}(0, \sigma_0^2 I_D)$, the relative entropy satisfies:
\begin{equation}
\label{eq:weight-space-divergence}
\mathrm{KL}(\pi_n \,\|\, \pi_0) \ge D \cdot (L - 1) \ln W + \frac{\|\hat{\theta}\|_2^2}{2\sigma_0^2} - \frac{D}{2} = \Omega\big(D \cdot L \ln W\big).
\end{equation}

\label{def:dirichlet-process}
Let $(\mathcal{Z}, \mathcal{B})$ be a measurable space. Let $\alpha > 0$ be a concentration parameter, and let $F_0 \in \mathcal{M}_1(\mathcal{Z})$ be a base probability measure. A random probability measure $P$ on $(\mathcal{Z}, \mathcal{B})$ is distributed according to the \textbf{Dirichlet Process}, denoted $P \sim \mathcal{DP}(\alpha, F_0)$, if for every finite measurable partition $\mathcal{P} = \{A_1, \dots, A_K\}$ of $\mathcal{Z}$, the random probability vector $(P(A_1), \dots, P(A_K))$ follows a Dirichlet distribution:
\begin{equation}
\big(P(A_1), \dots, P(A_K)\big) \sim \mathrm{Dir}\big(\alpha F_0(A_1), \, \dots, \, \alpha F_0(A_K)\big).
\end{equation}

\label{prop:measurability}
Let $(\mathcal{Z}, d_{\mathcal{Z}})$ be a compact metric space, and let $\mathcal{M}_1(\mathcal{Z})$ be equipped with the weak topology. Let the parameter space $\Theta \subseteq \mathbb{R}^D$ be closed and convex, and let $(z, \theta) \mapsto \ell(f_\theta(x), y)$ be continuous on $\mathcal{Z} \times \Theta$ and non-negative. Then Assumption~\ref{ass:learning-map} holds in each of the following settings:
\begin{enumerate}
    \item \textbf{Regularized Empirical Risk Minimization:} For any $\lambda > 0$, the $L_2$-regularized mapping
    \begin{equation}
    \label{eq:regularized-erm-map}
    \mathcal{A}_{\mathrm{ERM}}(P) \coloneqq \arg\min_{\theta \in \Theta} \left( \int_{\mathcal{Z}} \ell(f_\theta(x), y) \, dP(x, y) + \frac{\lambda}{2} \|\theta\|_2^2 \right)
    \end{equation}
    is single-valued and continuous with respect to the weak topology, and therefore strictly Borel measurable.
    \item \textbf{$T$-Step Gradient Descent:} If $\nabla_\theta \ell(f_\theta(x), y)$ is continuous on $\mathcal{Z} \times \Theta$ and bounded, then for any fixed initialization $\theta_0 \in \Theta$, learning rate $\eta > 0$, and horizon $T \in \mathbb{N}$, the gradient descent mapping $\mathcal{A}_T(P) \coloneqq \theta_T(P)$ defined by the iteration
    \begin{equation}
    \label{eq:gd-recurrence}
    \theta_{t+1}(P) = \theta_t(P) - \eta \int_{\mathcal{Z}} \nabla_\theta \ell(f_{\theta_t(P)}(x), y) \, dP(x, y), \qquad t = 0, \dots, T-1,
    \end{equation}
    is continuous on $\mathcal{M}_1(\mathcal{Z})$, and therefore strictly Borel measurable.
\end{enumerate}

\label{thm:dpi-invariance}
Let Assumption~\ref{ass:learning-map} hold. Let $\pi_0 = \mathcal{A}_\# \mathcal{P}_0$ and $\pi_n = \mathcal{A}_\# \mathcal{Q}_n$ be the push-forward prior and posterior distributions on parameter space $\Theta$. Then:
\begin{equation}
\label{eq:fundamental-dpi}
\mathrm{KL}(\pi_n \,\|\, \pi_0) \le \mathrm{KL}(\mathcal{Q}_n \,\|\, \mathcal{P}_0).
\end{equation}

\label{thm:closed-form-kl}
Let $\mathcal{P} = \{A_1, \dots, A_K\}$ be a finite measurable partition of $\mathcal{Z}$. Let $a_k = \alpha F_0(A_k)$ and $n_k = \sum_{i=1}^n \mathbf{1}\{z_i \in A_k\}$ denote the prior mass and empirical sample counts in partition cell $A_k$, satisfying $\sum_{k=1}^K a_k = \alpha$ and $\sum_{k=1}^K n_k = n$. 

Then the relative entropy between the projected DP posterior $\mathcal{Q}_n$ and prior $\mathcal{P}_0$ over partition $\mathcal{P}$ is given exactly by:
\begin{equation}
\label{eq:exact-partition-formula}
\mathrm{KL}_{\mathcal{P}}(\mathcal{Q}_n \,\|\, \mathcal{P}_0) = \ln \frac{\Gamma(\alpha + n)}{\Gamma(\alpha)} - \sum_{k=1}^K \ln \frac{\Gamma(a_k + n_k)}{\Gamma(a_k)} + \sum_{k=1}^K n_k \Big( \psi(a_k + n_k) - \psi(\alpha + n) \Big),
\end{equation}
where $\Gamma(z) = \int_0^\infty t^{z-1} e^{-t} dt$ is the Gamma function and $\psi(z) = \frac{d}{dz} \ln \Gamma(z)$ is the Digamma function.

\label{thm:main-certificate}
Let Assumptions~\ref{ass:bounded-loss} and \ref{ass:learning-map} hold. Let $\mathcal{P}_0 = \mathcal{DP}(\alpha, F_0)$ be a DP prior on $\mathcal{Z}$, and let $\mathcal{Q}_n$ be the conjugate posterior after observing $n$ samples. For \textbf{any} measurable partition $\mathcal{P} = \{A_1, \dots, A_K\}$ of $\mathcal{Z}$, with probability at least $1 - \delta$ over $S \sim \mathcal{D}^n$:
\begin{equation}
\label{eq:catoni-dp-bound}
\mathrm{kl}\big(\hat{R}_S(\pi_n) \,\|\, R(\pi_n)\big) \le \frac{\mathrm{KL}_{\mathcal{P}}(\mathcal{Q}_n \,\|\, \mathcal{P}_0) + \ln \frac{2\sqrt{n}}{\delta}}{n},
\end{equation}
where $\mathrm{kl}(q \,\|\, p) = q \ln \frac{q}{p} + (1 - q) \ln \frac{1 - q}{1 - p}$ is the binary relative entropy, and $\mathrm{KL}_{\mathcal{P}}(\mathcal{Q}_n \,\|\, \mathcal{P}_0)$ is computed in exact closed form via Equation~\eqref{eq:exact-partition-formula}. Inverting $\mathrm{kl}$ via Pinsker's inequality yields the explicit square-root certificate:
\begin{equation}
\label{eq:dimension-free-final-bound}
R(\pi_n) \le \hat{R}_S(\pi_n) + \sqrt{\frac{\mathrm{KL}_{\mathcal{P}}(\mathcal{Q}_n \,\|\, \mathcal{P}_0) + \ln \frac{2\sqrt{n}}{\delta}}{2n}}.
\end{equation}
In particular, both bounds are \textbf{strictly invariant to the neural network parameter dimension $D = \mathrm{dim}(\Theta)$}, depth $L$, and width $W$.

Let $f_\theta: \mathcal{X} \to \mathcal{Y}$ be an $L$-layer neural network parameterized by $\theta = (W_1, \dots, W_L) \in \mathbb{R}^D$:
\begin{equation}
f_\theta(x) = W_L \sigma(W_{L-1} \dots \sigma(W_1 x)),
\end{equation}
where $\sigma$ is a 1-Lipschitz activation function (such as ReLU). Let $\hat{\theta}$ be an empirical risk minimizer, and consider a Gaussian posterior perturbation $\theta = \hat{\theta} + \epsilon$ where $\epsilon \sim \mathcal{N}(0, \sigma_{\mathrm{post}}^2 I_D)$. 

By first-order Taylor expansion and the chain rule across $L$ layers:
\begin{equation}
f_{\hat{\theta} + \epsilon}(x) - f_{\hat{\theta}}(x) = \sum_{l=1}^L \left( \prod_{j=l+1}^L W_j \Sigma'_j \right) \epsilon_l \left( \prod_{k=1}^{l-1} \Sigma'_k W_k x \right) + \mathcal{O}(\|\epsilon\|^2),
\end{equation}
where $\Sigma'_j$ are diagonal derivative matrices satisfying $\|\Sigma'_j\|_{\mathrm{op}} \le 1$. If each layer has nominal width $W$ with balanced weight norms $\|W_l\|_{\mathrm{op}} \sim \mathcal{O}(1)$, the spectral radius of the compositional operator scales as $M_L = \sup_x \|\nabla_\theta f_\theta(x)\|_{\mathrm{op}} \ge c \cdot W^{L-1}$ for some constant $c > 0$.

Under the hypothesis that the posterior preserves empirical risk within margin $\epsilon_0$, we must have:
\begin{equation}
\mathbb{E}_{\epsilon}[|f_{\hat{\theta} + \epsilon}(x) - f_{\hat{\theta}}(x)|] \approx M_L \cdot \sigma_{\mathrm{post}} \le \epsilon_0 \implies \sigma_{\mathrm{post}} \le \frac{\epsilon_0}{c \cdot W^{L-1}}.
\end{equation}
Now, computing the Kullback--Leibler divergence between two multivariate Gaussians in $\mathbb{R}^D$ with $\pi_0 = \mathcal{N}(0, \sigma_0^2 I_D)$ and $\pi_n = \mathcal{N}(\hat{\theta}, \sigma_{\mathrm{post}}^2 I_D)$:
\begin{align}
\mathrm{KL}(\pi_n \,\|\, \pi_0) &= \frac{1}{2} \left[ \mathrm{tr}\left( \frac{\sigma_{\mathrm{post}}^2}{\sigma_0^2} I_D \right) - D - \ln \det\left( \frac{\sigma_{\mathrm{post}}^2}{\sigma_0^2} I_D \right) + \frac{\|\hat{\theta}\|_2^2}{\sigma_0^2} \right] \nonumber \\
&= \frac{1}{2} \left[ D \left( \frac{\sigma_{\mathrm{post}}^2}{\sigma_0^2} - 1 - \ln \frac{\sigma_{\mathrm{post}}^2}{\sigma_0^2} \right) + \frac{\|\hat{\theta}\|_2^2}{\sigma_0^2} \right].
\end{align}
Substituting the upper bound $\sigma_{\mathrm{post}} \le \frac{\epsilon_0}{c \cdot W^{L-1}}$:
\begin{align}
-\ln \frac{\sigma_{\mathrm{post}}^2}{\sigma_0^2} &\ge 2(L-1) \ln W + 2 \ln \left( \frac{c \sigma_0}{\epsilon_0} \right).
\end{align}
Since $\frac{\sigma_{\mathrm{post}}^2}{\sigma_0^2} \ge 0$, we obtain:
\begin{equation}
\mathrm{KL}(\pi_n \,\|\, \pi_0) \ge D \cdot (L-1) \ln W + \frac{D}{2} \left[ 2 \ln\left(\frac{c\sigma_0}{\epsilon_0}\right) - 1 \right] + \frac{\|\hat{\theta}\|_2^2}{2\sigma_0^2} = \Omega\big(D \cdot L \ln W\big),
\end{equation}
which establishes the claim.

Let $(\mathcal{Z}, d_{\mathcal{Z}})$ be a compact metric space. By the Banach--Alaoglu and Portmanteau theorems, the space $\mathcal{M}_1(\mathcal{Z})$ of Borel probability measures on $\mathcal{Z}$, equipped with the weak topology (the initial topology generated by bounded continuous test functions $C_b(\mathcal{Z})$), is a compact, metrizable Polish space \citep{billingsley2013convergence}. A compatible metric generating this topology is the Wasserstein-1 metric $W_1(P, Q) = \sup_{\|g\|_{\mathrm{Lip}} \le 1} |\int g \, d(P - Q)|$ or the Prokhorov metric. The Borel $\sigma$-algebra $\mathcal{B}(\mathcal{M}_1(\mathcal{Z}))$ generated by this weak topology coincides with the cylindrical $\sigma$-algebra generated by the evaluation projections $P \mapsto P(B)$ for all $B \in \mathcal{B}(\mathcal{Z})$.

To prove that a deterministic mapping $\mathcal{A}: \mathcal{M}_1(\mathcal{Z}) \to \Theta \subseteq \mathbb{R}^D$ is $(\mathcal{B}(\mathcal{M}_1(\mathcal{Z})), \mathcal{B}_\Theta)$-measurable, it suffices to prove that $\mathcal{A}$ is continuous with respect to the weak topology, since every continuous map between metric spaces is Borel measurable.

\@startsection{paragraph}{4}{\z@}{1.5ex plus
0.5ex minus .2ex}{-1em}{\normalsize\bf}{Part (i): Regularized Empirical Risk Minimization.}
Define the regularized risk functional $J: \Theta \times \mathcal{M}_1(\mathcal{Z}) \to \mathbb{R}$ by:
\begin{equation}
J(\theta, P) = \int_{\mathcal{Z}} \ell(f_\theta(x), y) \, dP(x, y) + \frac{\lambda}{2} \|\theta\|_2^2.
\end{equation}
For every fixed $P \in \mathcal{M}_1(\mathcal{Z})$, since $\ell \ge 0$ and the regularizer $\theta \mapsto \frac{\lambda}{2}\|\theta\|_2^2$ is $\lambda$-strongly convex on the closed convex set $\Theta$, the functional $J(\cdot, P)$ is strictly convex and coercive: $\lim_{\|\theta\| \to \infty} J(\theta, P) = \infty$. Consequently, the minimizer $\mathcal{A}_{\mathrm{ERM}}(P) = \arg\min_{\theta \in \Theta} J(\theta, P)$ exists and is unique for every $P \in \mathcal{M}_1(\mathcal{Z})$.

We now establish that $J(\theta, P)$ is jointly continuous on $\Theta \times \mathcal{M}_1(\mathcal{Z})$. Let $(\theta_m, P_m) \to (\theta, P)$ where $\theta_m \to \theta$ in Euclidean norm on $\mathbb{R}^D$ and $P_m \xrightarrow{w} P$ weakly. Decomposing the difference:
\begin{align}
|J(\theta_m, P_m) - J(\theta, P)| &\le \left| \int_{\mathcal{Z}} \left( \ell(f_{\theta_m}(x), y) - \ell(f_\theta(x), y) \right) dP_m(x, y) \right| \nonumber \\
&\quad + \left| \int_{\mathcal{Z}} \ell(f_\theta(x), y) \, d(P_m - P)(x, y) \right| + \frac{\lambda}{2} \left| \|\theta_m\|_2^2 - \|\theta\|_2^2 \right|.
\end{align}
Because $\mathcal{Z}$ is compact and $(z, \theta) \mapsto \ell(f_\theta(x), y)$ is continuous, the family of functions $\{\ell(f_{\theta_m}(\cdot), \cdot)\}$ converges uniformly to $\ell(f_\theta(\cdot), \cdot)$ on $\mathcal{Z}$ as $\theta_m \to \theta$ by the Heine--Cantor theorem. Thus:
\begin{equation}
\sup_{z \in \mathcal{Z}} |\ell(f_{\theta_m}(x), y) - \ell(f_\theta(x), y)| \xrightarrow{m \to \infty} 0,
\end{equation}
which bounds the first integral uniformly over all probability measures $P_m$:
\begin{equation}
\left| \int_{\mathcal{Z}} \left( \ell(f_{\theta_m}(x), y) - \ell(f_\theta(x), y) \right) dP_m \right| \le \sup_{z \in \mathcal{Z}} |\ell(f_{\theta_m}(x), y) - \ell(f_\theta(x), y)| \xrightarrow{m \to \infty} 0.
\end{equation}
The second term vanishes because $z \mapsto \ell(f_\theta(x), y)$ is a bounded continuous test function on compact $\mathcal{Z}$ and $P_m \xrightarrow{w} P$ weakly. The third term vanishes by continuity of the Euclidean norm. Hence $J$ is jointly continuous.

By Berge's Maximum Theorem \citep{berge1963topological}, the argmin correspondence $P \mapsto \arg\min_{\theta \in \Theta} J(\theta, P)$ is upper hemicontinuous. Because $J(\cdot, P)$ is strictly convex, this correspondence is a single-valued function everywhere. An upper hemicontinuous single-valued correspondence into a Hausdorff space is continuous. Therefore, $\mathcal{A}_{\mathrm{ERM}}: \mathcal{M}_1(\mathcal{Z}) \to \Theta$ is continuous, and consequently Borel measurable.

\@startsection{paragraph}{4}{\z@}{1.5ex plus
0.5ex minus .2ex}{-1em}{\normalsize\bf}{Part (ii): $T$-Step Gradient Descent.}
Let $\theta_0 \in \Theta$ be fixed. Define the gradient integration operator $G: \Theta \times \mathcal{M}_1(\mathcal{Z}) \to \mathbb{R}^D$ by:
\begin{equation}
G(\theta, P) = \int_{\mathcal{Z}} \nabla_\theta \ell(f_\theta(x), y) \, dP(x, y).
\end{equation}
We show that $G$ is jointly continuous. Let $(\theta_m, P_m) \to (\theta, P)$. By the triangle inequality:
\begin{equation}
\|G(\theta_m, P_m) - G(\theta, P)\|_2 \le \int_{\mathcal{Z}} \|\nabla_\theta \ell(f_{\theta_m}(x), y) - \nabla_\theta \ell(f_\theta(x), y)\|_2 \, dP_m + \left\| \int_{\mathcal{Z}} \nabla_\theta \ell(f_\theta(x), y) \, d(P_m - P) \right\|_2.
\end{equation}
By uniform continuity of the gradient on compact subsets of $\mathcal{Z} \times \Theta$, $\sup_{z \in \mathcal{Z}} \|\nabla_\theta \ell(f_{\theta_m}(x), y) - \nabla_\theta \ell(f_\theta(x), y)\|_2 \to 0$, vanishing the first term. The second term vanishes coordinate-wise because each component $z \mapsto \frac{\partial}{\partial \theta_j} \ell(f_\theta(x), y)$ is a bounded continuous test function under weak convergence $P_m \xrightarrow{w} P$. Hence $G(\theta, P)$ is jointly continuous.

We proceed by induction on $t \in \{0, 1, \dots, T\}$. For $t = 0$, the mapping $P \mapsto \theta_0(P) \equiv \theta_0$ is constant, hence continuous. Now assume $\theta_t: \mathcal{M}_1(\mathcal{Z}) \to \Theta$ is continuous. The recurrence relation is:
\begin{equation}
\theta_{t+1}(P) = \theta_t(P) - \eta G(\theta_t(P), P).
\end{equation}
Since $\theta_{t+1}$ is the composition of the continuous map $P \mapsto (\theta_t(P), P)$ with the continuous map $(\theta, P) \mapsto \theta - \eta G(\theta, P)$, it follows that $\theta_{t+1}: \mathcal{M}_1(\mathcal{Z}) \to \Theta$ is continuous. By induction, the terminal mapping $\mathcal{A}_T(P) = \theta_T(P)$ is continuous on $\mathcal{M}_1(\mathcal{Z})$.

Since every continuous map between metric spaces is Borel measurable, $\mathcal{A}_T$ is strictly $(\mathcal{B}(\mathcal{M}_1(\mathcal{Z})), \mathcal{B}_\Theta)$-measurable, which completes the proof.

Let $\mathcal{P} = \{A_1, \dots, A_K\}$ be a partition of $\mathcal{Z}$. Under $\mathcal{P}_0 = \mathcal{DP}(\alpha, F_0)$, the random vector $\mathbf{p} = (P(A_1), \dots, P(A_K))$ is distributed as $\mathrm{Dir}(\mathbf{a})$ with $\mathbf{a} = (a_1, \dots, a_K)$ and $a_k = \alpha F_0(A_k)$, where $a_0 = \sum_{k=1}^K a_k = \alpha$.

Under the posterior $\mathcal{Q}_n = \mathcal{DP}(\alpha + n, \frac{\alpha F_0 + n \mathbb{P}_n}{\alpha + n})$, the parameter vector updates to $\mathbf{b} = (b_1, \dots, b_K)$ with $b_k = a_k + n_k$, where $n_k = \sum_{i=1}^n \mathbf{1}\{z_i \in A_k\}$ and $b_0 = \sum_{k=1}^K b_k = \alpha + n$.

The density of $\mathrm{Dir}(\mathbf{b})$ with respect to Lebesgue measure on the simplex $\Delta_{K-1}$ is:
\begin{equation}
q_n(\mathbf{p}) = \frac{1}{\mathrm{B}(\mathbf{b})} \prod_{k=1}^K p_k^{b_k - 1}, \qquad \mathrm{B}(\mathbf{b}) = \frac{\prod_{k=1}^K \Gamma(b_k)}{\Gamma(b_0)}.
\end{equation}
Similarly, the prior density is $p_0(\mathbf{p}) = \frac{1}{\mathrm{B}(\mathbf{a})} \prod_{k=1}^K p_k^{a_k - 1}$. The relative entropy between two Dirichlet distributions on $\Delta_{K-1}$ is:
\begin{align}
\mathrm{KL}_{\mathcal{P}}(\mathcal{Q}_n \,\|\, \mathcal{P}_0) &= \int_{\Delta_{K-1}} q_n(\mathbf{p}) \ln \frac{q_n(\mathbf{p})}{p_0(\mathbf{p})} \, d\mathbf{p} \nonumber \\
&= \ln \frac{\mathrm{B}(\mathbf{a})}{\mathrm{B}(\mathbf{b})} + \sum_{k=1}^K (b_k - a_k) \mathbb{E}_{\mathbf{p} \sim \mathrm{Dir}(\mathbf{b})}[\ln p_k].
\end{align}
The ratio of multivariate Beta normalizing constants expands as:
\begin{equation}
\ln \frac{\mathrm{B}(\mathbf{a})}{\mathrm{B}(\mathbf{b})} = \ln \frac{\Gamma(b_0)}{\Gamma(a_0)} - \sum_{k=1}^K \ln \frac{\Gamma(b_k)}{\Gamma(a_k)} = \ln \frac{\Gamma(\alpha + n)}{\Gamma(\alpha)} - \sum_{k=1}^K \ln \frac{\Gamma(a_k + n_k)}{\Gamma(a_k)}.
\end{equation}
For any Dirichlet distribution $\mathbf{p} \sim \mathrm{Dir}(\mathbf{b})$, the marginal distribution of $p_k$ is a Beta distribution $\mathrm{Beta}(b_k, b_0 - b_k)$. The expected logarithm of a Beta-distributed random variable has the exact analytical form:
\begin{equation}
\mathbb{E}[\ln p_k] = \psi(b_k) - \psi(b_0) = \psi(a_k + n_k) - \psi(\alpha + n).
\end{equation}
Substituting $b_k - a_k = n_k$:
\begin{equation}
\sum_{k=1}^K (b_k - a_k) \mathbb{E}[\ln p_k] = \sum_{k=1}^K n_k \Big( \psi(a_k + n_k) - \psi(\alpha + n) \Big).
\end{equation}
Summing both terms gives:
\begin{equation}
\mathrm{KL}_{\mathcal{P}}(\mathcal{Q}_n \,\|\, \mathcal{P}_0) = \ln \frac{\Gamma(\alpha + n)}{\Gamma(\alpha)} - \sum_{k=1}^K \ln \frac{\Gamma(a_k + n_k)}{\Gamma(a_k)} + \sum_{k=1}^K n_k \Big( \psi(a_k + n_k) - \psi(\alpha + n) \Big),
\end{equation}
which is the exact analytical identity of Theorem~\ref{thm:closed-form-kl}.

\label{thm:metric-entropy-bound}
Let $\mathcal{Z}$ be a compact metric space whose data distribution is supported on an intrinsic $d^*$-dimensional Riemannian submanifold $\mathcal{M} \subset \mathbb{R}^d$ with covering number $\mathcal{N}(\mathcal{Z}, \epsilon, d_{\mathcal{Z}}) \le C_{\mathcal{M}} \epsilon^{-d^*}$. Assume the loss function $\ell$ is $L_\ell$-Lipschitz with respect to $d_{\mathcal{Z}}$. Then for any $\epsilon > 0$, with probability at least $1 - \delta$ over $S \sim \mathcal{D}^n$:
\begin{equation}
R(\pi_n) \le \hat{R}_S(\pi_n) + 2 L_{\ell} \epsilon + \sqrt{\frac{\mathrm{KL}_{\mathcal{P}_\epsilon}(\mathcal{Q}_n \,\|\, \mathcal{P}_0) + \ln \frac{2\sqrt{n}}{\delta}}{2n}},
\end{equation}
where $\mathcal{P}_\epsilon$ is an $\epsilon$-Voronoi partition with $K_\epsilon \le C_{\mathcal{M}} \epsilon^{-d^*}$.

Let $(\mathcal{Z}, d_{\mathcal{Z}})$ be a compact metric space with covering number $K_\epsilon = \mathcal{N}(\mathcal{Z}, \epsilon, d_{\mathcal{Z}})$. Let $\{c_1, \dots, c_{K_\epsilon}\} \subset \mathcal{Z}$ be a minimal $\epsilon$-net. Define the Voronoi partition $\mathcal{P}_\epsilon = \{A_1, \dots, A_{K_\epsilon}\}$ by:
\begin{equation}
A_k = \{z \in \mathcal{Z} : d_{\mathcal{Z}}(z, c_k) \le d_{\mathcal{Z}}(z, c_j) \; \forall j < k, \quad d_{\mathcal{Z}}(z, c_k) < d_{\mathcal{Z}}(z, c_j) \; \forall j > k\}.
\end{equation}
By construction, $\bigcup_{k=1}^{K_\epsilon} A_k = \mathcal{Z}$, $A_i \cap A_j = \emptyset$ for $i \neq j$, and $\sup_{z \in A_k} d_{\mathcal{Z}}(z, c_k) \le \epsilon$, which implies $\mathrm{diam}(A_k) \le 2\epsilon$.

Define the surrogate cell-centered loss $\bar{\ell}: \Theta \times \{1, \dots, K_\epsilon\} \to [0, 1]$ by $\bar{\ell}(\theta, k) = \ell(f_\theta(x_{c_k}), y_{c_k})$. For any $z = (x, y) \in A_k$, the $L_{\ell}$-Lipschitz assumption on $\ell$ yields:
\begin{equation}
|\ell(f_\theta(x), y) - \bar{\ell}(\theta, k)| \le L_{\ell} \cdot d_{\mathcal{Z}}(z, c_k) \le L_{\ell} \epsilon.
\end{equation}
Taking expectations over $z \sim \mathcal{D}$ and the sample $S$:
\begin{align}
|R(f_\theta) - \bar{R}(\theta)| &\le L_{\ell} \epsilon, \\
|\hat{R}_S(f_\theta) - \hat{\bar{R}}_S(\theta)| &\le L_{\ell} \epsilon.
\end{align}
Applying Theorem~\ref{thm:main-certificate} to the surrogate loss $\bar{\ell}$ over the finite partition $\mathcal{P}_\epsilon$:
\begin{equation}
\mathbb{E}_{\pi_n}[\bar{R}(f_\theta)] \le \mathbb{E}_{\pi_n}[\hat{\bar{R}}_S(f_\theta)] + \sqrt{\frac{\mathrm{KL}_{\mathcal{P}_\epsilon}(\mathcal{Q}_n \,\|\, \mathcal{P}_0) + \ln \frac{2\sqrt{n}}{\delta}}{2n}}.
\end{equation}
Applying the triangle inequality:
\begin{equation}
R(\pi_n) \le \bar{R}(\pi_n) + L_{\ell}\epsilon \le \hat{\bar{R}}_S(\pi_n) + L_{\ell}\epsilon + \sqrt{\dots} \le \hat{R}_S(\pi_n) + 2 L_{\ell}\epsilon + \sqrt{\frac{\mathrm{KL}_{\mathcal{P}_\epsilon}(\mathcal{Q}_n \,\|\, \mathcal{P}_0) + \ln \frac{2\sqrt{n}}{\delta}}{2n}}.
\end{equation}
Now, if $\mathcal{D}$ is supported on a $d^*$-dimensional Riemannian submanifold $\mathcal{M}$ with bounded curvature, by the Bishop--Gromov volume comparison theorem, the covering number satisfies $K_\epsilon \le C_{\mathcal{M}} \epsilon^{-d^*}$. 

By Stirling's approximation on Equation~\eqref{eq:exact-partition-formula}, $\mathrm{KL}_{\mathcal{P}_\epsilon} \le K_\epsilon \ln(1 + n/\alpha) \le C_{\mathcal{M}} \epsilon^{-d^*} \ln(n)$. Equating the discretization rate $2 L_{\ell} \epsilon$ with the estimation rate $\sqrt{C_{\mathcal{M}} \epsilon^{-d^*} \frac{\ln n}{2n}}$ yields:
\begin{equation}
\epsilon^{1 + \frac{d^*}{2}} \asymp \sqrt{\frac{\ln n}{n}} \implies \epsilon \asymp \left(\frac{\ln n}{n}\right)^{\frac{1}{d^* + 2}}.
\end{equation}
Substituting this optimal $\epsilon$ yields the manifold convergence rate:
\begin{equation}
R(\pi_n) - \hat{R}_S(\pi_n) \le \mathcal{O}\left( n^{-\frac{1}{d^* + 2}} \sqrt{\ln n} \right),
\end{equation}
which is completely independent of the ambient parameter dimension $D$.

\label{lem:optimal-partition}
Under the assumptions of Theorem~\ref{thm:metric-entropy-bound} with uniform base measure $F_0(A_k) = 1/K_\epsilon$, the discretization-estimation trade-off objective is strictly convex in $\epsilon$, admitting a unique global minimizer:
\begin{equation}
\label{eq:optimal-epsilon-star}
\epsilon^* = \left( \frac{(d^*)^2 C_{\mathcal{M}} \ln(1 + n/\alpha)}{32 L_{\ell}^2 n} \right)^{\frac{1}{d^* + 2}},
\end{equation}
and corresponding optimal partition size:
\begin{equation}
\label{eq:optimal-K-star}
K^* = C_{\mathcal{M}}^{\frac{2}{d^*+2}} \left( \frac{32 L_{\ell}^2 n}{(d^*)^2 \ln(1 + n/\alpha)} \right)^{\frac{d^*}{d^*+2}} \asymp n^{\frac{d^*}{d^*+2}}.
\end{equation}
Evaluating at $(\epsilon^*, K^*)$ achieves the minimax optimal excess risk rate $R(\pi_n) - \hat{R}_S(\pi_n) = \mathcal{O}\left( n^{-\frac{1}{d^*+2}} \sqrt{\ln n} \right)$, completely independent of network parameter dimension $D$.

From Theorem~\ref{thm:metric-entropy-bound}, the excess risk certificate is bounded by:
\begin{equation}
R(\pi_n) - \hat{R}_S(\pi_n) \le 2 L_{\ell} \epsilon + \sqrt{\frac{\mathrm{KL}_{\mathcal{P}_\epsilon}(\mathcal{Q}_n \,\|\, \mathcal{P}_0) + \ln \frac{2\sqrt{n}}{\delta}}{2n}}.
\end{equation}
Under the uniform base measure $F_0(A_k) = 1/K_\epsilon$, the partition parameters are $a_k = \alpha / K_\epsilon$. Applying the Dirichlet partition divergence bound from Theorem~\ref{thm:closed-form-kl}:
\begin{equation}
\mathrm{KL}_{\mathcal{P}_\epsilon}(\mathcal{Q}_n \,\|\, \mathcal{P}_0) \le K_\epsilon \ln\left(1 + \frac{n}{\alpha}\right).
\end{equation}
Substituting the metric entropy upper bound $K_\epsilon \le C_{\mathcal{M}} \epsilon^{-d^*}$ on the $d^*$-dimensional compact submanifold $\mathcal{M}$, the bound is dominated by the objective functional:
\begin{equation}
\mathcal{E}_n(\epsilon) = 2 L_{\ell} \epsilon + \sqrt{\frac{C_{\mathcal{M}} \epsilon^{-d^*} \ln(1 + n/\alpha) + \ln \frac{2\sqrt{n}}{\delta}}{2n}}.
\end{equation}
By the sub-additivity inequality $\sqrt{u + v} \le \sqrt{u} + \sqrt{v}$ for non-negative $u, v$:
\begin{equation}
\mathcal{E}_n(\epsilon) \le g(\epsilon) + \sqrt{\frac{\ln \frac{2\sqrt{n}}{\delta}}{2n}},
\end{equation}
where $g: (0, \infty) \to (0, \infty)$ is defined by:
\begin{equation}
g(\epsilon) \coloneqq A \epsilon + B_n \epsilon^{-d^*/2}, \qquad \text{with} \quad A = 2 L_{\ell} > 0, \quad B_n = \sqrt{\frac{C_{\mathcal{M}} \ln(1 + n/\alpha)}{2n}} > 0.
\end{equation}
Differentiating $g(\epsilon)$ with respect to $\epsilon$:
\begin{equation}
g'(\epsilon) = A - \frac{d^*}{2} B_n \epsilon^{-\frac{d^*+2}{2}}, \qquad g''(\epsilon) = \frac{d^*(d^*+2)}{4} B_n \epsilon^{-\frac{d^*+4}{2}}.
\end{equation}
Because $d^* \ge 1$, $A > 0$, and $B_n > 0$, the second derivative satisfies $g''(\epsilon) > 0$ for all $\epsilon > 0$. Hence $g(\epsilon)$ is strictly convex on $(0, \infty)$ and possesses a unique global minimizer $\epsilon^*$. Setting $g'(\epsilon^*) = 0$ yields:
\begin{equation}
A = \frac{d^*}{2} B_n (\epsilon^*)^{-\frac{d^*+2}{2}} \implies (\epsilon^*)^{\frac{d^*+2}{2}} = \frac{d^* B_n}{2 A}.
\end{equation}
Squaring both sides:
\begin{equation}
(\epsilon^*)^{d^*+2} = \frac{(d^*)^2 B_n^2}{4 A^2} = \frac{(d^*)^2 \cdot \frac{C_{\mathcal{M}} \ln(1 + n/\alpha)}{2n}}{4 \cdot (2 L_{\ell})^2} = \frac{(d^*)^2 C_{\mathcal{M}} \ln(1 + n/\alpha)}{32 L_{\ell}^2 n}.
\end{equation}
Taking the $(d^*+2)$-th root establishes Equation~\eqref{eq:optimal-epsilon-star}:
\begin{equation}
\epsilon^* = \left( \frac{(d^*)^2 C_{\mathcal{M}} \ln(1 + n/\alpha)}{32 L_{\ell}^2 n} \right)^{\frac{1}{d^* + 2}}.
\end{equation}
Substituting $\epsilon^*$ into $K^* = C_{\mathcal{M}} (\epsilon^*)^{-d^*}$ immediately gives Equation~\eqref{eq:optimal-K-star}:
\begin{equation}
K^* = C_{\mathcal{M}} \left( \frac{32 L_{\ell}^2 n}{(d^*)^2 C_{\mathcal{M}} \ln(1 + n/\alpha)} \right)^{\frac{d^*}{d^*+2}} = C_{\mathcal{M}}^{\frac{2}{d^*+2}} \left( \frac{32 L_{\ell}^2 n}{(d^*)^2 \ln(1 + n/\alpha)} \right)^{\frac{d^*}{d^*+2}}.
\end{equation}
Evaluating the objective $g$ at $\epsilon^*$, noting that $B_n (\epsilon^*)^{-d^*/2} = \frac{2 A}{d^*} \epsilon^*$:
\begin{equation}
g(\epsilon^*) = A \epsilon^* + \frac{2 A}{d^*} \epsilon^* = \left( 1 + \frac{2}{d^*} \right) A \epsilon^* = \frac{d^* + 2}{d^*} \cdot 2 L_{\ell} \epsilon^*.
\end{equation}
Substituting the explicit formula for $\epsilon^*$ and re-introducing the confidence term:
\begin{equation}
\mathcal{E}_n(\epsilon^*) \le \frac{d^* + 2}{d^*} \cdot 2 L_{\ell} \left( \frac{(d^*)^2 C_{\mathcal{M}} \ln(1 + n/\alpha)}{32 L_{\ell}^2 n} \right)^{\frac{1}{d^*+2}} + \sqrt{\frac{\ln \frac{2\sqrt{n}}{\delta}}{2n}}.
\end{equation}
Since $\frac{\ln(1 + n/\alpha)}{n} = \mathcal{O}\left(\frac{\ln n}{n}\right)$, the dominant term scales as:
\begin{equation}
\mathcal{E}_n(\epsilon^*) = \mathcal{O}\left( n^{-\frac{1}{d^*+2}} (\ln n)^{\frac{1}{d^*+2}} \right) + \mathcal{O}\left( n^{-1/2} \sqrt{\ln n} \right) = \mathcal{O}\left( n^{-\frac{1}{d^*+2}} \sqrt{\ln n} \right),
\end{equation}
matching the minimax non-parametric convergence rate \citep{tsybakov2009introduction} on a $d^*$-dimensional manifold, and concluding the proof.
